"""Compare baseline vs refactored probe results (status, shape, normalized body)."""
import json
import re
import sys

VOLATILE = {"timestamp", "created_at", "updated_at", "generated_at", "token", "due_date"}


def norm(value):
    if isinstance(value, dict):
        return {k: ("<v>" if k in VOLATILE else norm(v)) for k, v in value.items() if k != "password"}
    if isinstance(value, list):
        return [norm(v) for v in value]
    if isinstance(value, str) and re.match(r"^\d{4}-\d{2}-\d{2} ", value):
        return "<v>"
    return value


before = {r["name"]: r for r in json.load(open(sys.argv[1]))}
after = {r["name"]: r for r in json.load(open(sys.argv[2]))}
same = diff = 0
for name, b in before.items():
    a = after[name]
    problems = []
    if a["status"] != b["status"]:
        problems.append(f'status {b["status"]} -> {a["status"]}')
    if a["shape"] != b["shape"]:
        problems.append(f'shape {b["shape"]} -> {a["shape"]}')
    if norm(a["body"]) != norm(b["body"]):
        problems.append(f'body {json.dumps(norm(b["body"]), ensure_ascii=False)[:300]}\n      -> {json.dumps(norm(a["body"]), ensure_ascii=False)[:300]}')
    if problems:
        diff += 1
        print(f'DIFF {name} {b["method"]} {b["path"]}:\n   ' + "\n   ".join(problems))
    else:
        same += 1
print(f"\nidentical: {same}  different: {diff}  (extra refactored-only probes: {sorted(set(after) - set(before))})")
for name in sorted(set(after) - set(before)):
    print("  ", name, after[name]["status"], after[name]["body"])

