import ast
import os
import sys

root = sys.argv[1]
found = 0
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in {".venv", ".git", "__pycache__", ".claude", "instance"}]
    for filename in filenames:
        if not filename.endswith(".py"):
            continue
        path = os.path.join(dirpath, filename)
        source = open(path).read()
        tree = ast.parse(source)
        imported = {}
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                for alias in node.names:
                    name = (alias.asname or alias.name).split(".")[0]
                    imported[name] = node.lineno
        used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
               {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
        for name, line in imported.items():
            if name not in used and not filename == "__init__.py" and "noqa" not in source.splitlines()[line - 1]:
                found += 1
                print(f"{os.path.relpath(path, root)}:{line} unused import {name}")
print("unused imports:", found)

